    CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL,birth_date TEXT NOT NULL,display_id TEXT NOT NULL,created_at TEXT NOT NULL,last_active TEXT NOT NULL,email_verified INTEGER NOT NULL DEFAULT 0,email_notifications INTEGER NOT NULL DEFAULT 1);
    CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS profiles(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'draft',data_json TEXT NOT NULL,approved_json TEXT,verified INTEGER NOT NULL DEFAULT 0,photo_id TEXT);
    CREATE TABLE IF NOT EXISTS applications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,data_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'payment_pending',paid INTEGER NOT NULL DEFAULT 0,payment_ref TEXT,paypal_order TEXT,created_at TEXT NOT NULL,review_started_at TEXT,review_reason TEXT,paid_at TEXT,decided_at TEXT,approval_method TEXT);
    CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY,donor_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,recipient_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'requested',disclosed INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,UNIQUE(donor_id,recipient_id));
    CREATE TABLE IF NOT EXISTS files(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,application_id TEXT REFERENCES applications(id) ON DELETE CASCADE,conversation_id TEXT REFERENCES conversations(id) ON DELETE CASCADE,kind TEXT NOT NULL,file_key TEXT NOT NULL,mime TEXT NOT NULL,original_name TEXT NOT NULL,created_at TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,sender_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,body TEXT NOT NULL,file_id TEXT REFERENCES files(id) ON DELETE SET NULL,created_at TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,donor_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,recipient_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,occurred_on TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS chat_tombstones(id TEXT PRIMARY KEY,survivor_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,hits INTEGER NOT NULL,expires_at BIGINT NOT NULL);
    CREATE TABLE IF NOT EXISTS file_gc(file_key TEXT PRIMARY KEY);
    CREATE TABLE IF NOT EXISTS catalog(id TEXT PRIMARY KEY,kind TEXT NOT NULL,school TEXT NOT NULL,faculty TEXT NOT NULL,department TEXT NOT NULL,deviation DOUBLE PRECISION NOT NULL,year INTEGER NOT NULL,source_url TEXT NOT NULL);
    CREATE INDEX IF NOT EXISTS message_time ON messages(conversation_id,created_at);
    CREATE INDEX IF NOT EXISTS file_owner ON files(owner_id);
    CREATE INDEX IF NOT EXISTS applications_owner ON applications(user_id,created_at);
    
CREATE TABLE IF NOT EXISTS email_tokens(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,email TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mail_queue(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,conversation_id TEXT REFERENCES conversations(id) ON DELETE CASCADE,kind TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,next_attempt BIGINT NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS review_mail(application_id TEXT PRIMARY KEY REFERENCES applications(id) ON DELETE CASCADE,recipient TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_attempt BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS support_tickets(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT,category TEXT NOT NULL,subject TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS support_messages(id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE,sender TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS support_owner ON support_tickets(user_id,updated_at);
CREATE INDEX IF NOT EXISTS support_thread ON support_messages(ticket_id,created_at);
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,conversation_id TEXT REFERENCES conversations(id) ON DELETE CASCADE,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,reason TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS service_leases(key TEXT PRIMARY KEY,expires_at BIGINT NOT NULL);

